def fill_start_time_and_payment_status(apps, schema_editor):
    """داده‌ی نوبت‌های موجود: ساعت از شیفت، وضعیت پرداخت از وضعیت نوبت."""
    Appointment = apps.get_model("appointments", "Appointment")

    for appointment in Appointment.objects.select_related("availability"):
        appointment.start_time = appointment.availability.time
        # «تأییدشده/انجام‌شده» در سیستم قبلی یعنی پرداخت توسط ادمین تأیید شده بود
        appointment.payment_status = "paid" if appointment.status in ("confirmed", "completed") else "unpaid"
        appointment.save(update_fields=["start_time", "payment_status"])


